    [InlineData("bfs.ts", "function reachable(graph: number[][], start: number, goal: number): boolean {\n  const queue: number[] = [start];\n  const seen = new Set<number>([start]);\n  while (queue.length > 0) {\n    const node = queue.shift() as number;\n    if (node === goal) {\n      return true;\n    }\n    for (const successor of graph[node]) {\n      if (!seen.has(successor)) {\n        seen.add(successor);\n        queue.push(successor);\n      }\n    }\n  }\n  return false;\n}\n\nconst graph: number[][] = [[1, 2], [3], [3], [], [0]];\nconsole.log(reachable(graph, 0, 4) ? \"reached\" : \"not reached\");\n")]
    [InlineData("Program.cs", "using System;\nusing System.Collections.Generic;\n\npublic static class Program\n{\n    static bool Reachable(int[][] graph, int start, int goal)\n    {\n        var queue = new Queue<int>();\n        queue.Enqueue(start);\n        var seen = new HashSet<int> { start };\n        while (queue.Count > 0)\n        {\n            var node = queue.Dequeue();\n            if (node == goal)\n            {\n                return true;\n            }\n\n            foreach (var successor in graph[node])\n            {\n                if (seen.Add(successor))\n                {\n                    queue.Enqueue(successor);\n                }\n            }\n        }\n\n        return false;\n    }\n\n    public static void Main()\n    {\n        int[][] graph = { new[] { 1, 2 }, new[] { 3 }, new[] { 3 }, Array.Empty<int>(), new[] { 0 } };\n        Console.WriteLine(Reachable(graph, 0, 4) ? \"reached\" : \"not reached\");\n    }\n}\n")]
    [InlineData("Reach.java", "import java.util.ArrayDeque;\nimport java.util.HashSet;\nimport java.util.List;\nimport java.util.Set;\n\npublic class Reach {\n    static boolean reachable(List<List<Integer>> graph, int start, int goal) {\n        ArrayDeque<Integer> queue = new ArrayDeque<>();\n        queue.addLast(start);\n        Set<Integer> seen = new HashSet<>(Set.of(start));\n        while (!queue.isEmpty()) {\n            int node = queue.removeFirst();\n            if (node == goal) {\n                return true;\n            }\n            for (int successor : graph.get(node)) {\n                if (seen.add(successor)) {\n                    queue.addLast(successor);\n                }\n            }\n        }\n        return false;\n    }\n\n    public static void main(String[] args) {\n        List<List<Integer>> graph = List.of(List.of(1, 2), List.of(3), List.of(3), List.of(), List.of(0));\n        System.out.println(reachable(graph, 0, 4) ? \"reached\" : \"not reached\");\n    }\n}\n")]
